def investigate(context, acquire):
    hist = acquire("history")

    def simulate(actions, mode, trig, chan):
        committed = {}
        pending = {"main": None, "other": None}
        tc = {"main": 0, "other": 0}
        last_changes = {"main": 0, "other": 0}

        def view_of(conn):
            if pending[conn] is not None:
                v = dict(committed)
                v.update(pending[conn])
                return v
            return committed

        def write(conn, key, value, changed):
            if changed:
                if pending[conn] is not None:
                    pending[conn][key] = value
                else:
                    committed[key] = value
                tc[conn] += 1
            last_changes[conn] = changed

        def do_put(conn, key, value):
            view = view_of(conn)
            if mode == "ignore":
                changed = 1 if key not in view else 0
            elif mode == "replace":
                changed = 1
            else:
                if key in view:
                    changed = 1 if view[key] != value else 0
                else:
                    changed = 1
            write(conn, key, value, changed)

        def do_update(conn, key, value):
            view = view_of(conn)
            changed = 1 if (key in view and view[key] != value) else 0
            write(conn, key, value, changed)

        def do_delete(conn, key):
            view = view_of(conn)
            changed = 1 if key in view else 0
            if changed:
                if pending[conn] is not None:
                    del pending[conn][key]
                else:
                    del committed[key]
                tc[conn] += 1
            last_changes[conn] = changed

        for act in actions:
            op = act.get("op")
            conn = act.get("connection", "main")
            if op == "put":
                do_put(conn, act["key"], act["value"])
            elif op == "update":
                do_update(conn, act["key"], act["value"])
            elif op == "delete":
                do_delete(conn, act["key"])
            elif op == "begin":
                pending[conn] = {}
            elif op == "commit":
                if pending[conn] is not None:
                    committed.update(pending[conn])
                    pending[conn] = None
            elif op == "rollback":
                pending[conn] = None

        if chan == "changes":
            ch = last_changes["main"]
        elif chan == "total_changes":
            ch = tc["main"]
        else:
            ch = tc["main"] + tc["other"]
        return ch, len(committed), sum(committed.values())

    modes = ["ignore", "replace", "upsert"]
    trigs = [False, True]
    chans = ["changes", "total_changes", "total_changes_sum"]

    candidates = []
    for mode in modes:
        for trig in trigs:
            for chan in chans:
                ok = True
                for rec in hist:
                    acts = rec.get("actions", [])
                    obs = rec.get("observed", {})
                    ch, cc, cs = simulate(acts, mode, trig, chan)
                    if ch != obs.get("channel") or cc != obs.get("committed_count") or cs != obs.get("committed_sum"):
                        ok = False
                        break
                if ok:
                    candidates.append((mode, trig, chan))

    if not candidates:
        return {"value": None, "unresolved": True}

    goal = context.get("goal")
    actions = context.get("actions", [])
    vals = set()
    for mode, trig, chan in candidates:
        ch, cc, cs = simulate(actions, mode, trig, chan)
        if goal == "channel":
            vals.add(ch)
        elif goal == "committed_count":
            vals.add(cc)
        elif goal == "committed_sum":
            vals.add(cs)
        else:
            return {"value": None, "unresolved": True}
    if len(vals) == 1:
        return {"value": vals.pop(), "unresolved": False}
    return {"value": None, "unresolved": True}

